package edu.uiu.aoop.careerforge.config;
import edu.uiu.aoop.careerforge.security.JwtAuthenticationFilter; import edu.uiu.aoop.careerforge.security.LoginRateLimitFilter; import java.util.List; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*;
@Configuration @EnableWebSecurity @EnableMethodSecurity public class SecurityConfig {
 private final JwtAuthenticationFilter jwt; private final LoginRateLimitFilter loginRateLimit; private final String origins; public SecurityConfig(JwtAuthenticationFilter jwt,LoginRateLimitFilter loginRateLimit,@Value("${careerforge.cors.origins}") String origins){this.jwt=jwt;this.loginRateLimit=loginRateLimit;this.origins=origins;}
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean CorsConfigurationSource corsConfigurationSource(){ var c=new CorsConfiguration(); c.setAllowedOrigins(List.of(origins.split(","))); c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS")); c.setAllowedHeaders(List.of("Authorization","Content-Type")); c.setAllowCredentials(true); var source=new UrlBasedCorsConfigurationSource(); source.registerCorsConfiguration("/**",c); return source; }
 @Bean SecurityFilterChain filterChain(HttpSecurity http) throws Exception { return http.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/auth/**","/health").permitAll().requestMatchers(HttpMethod.OPTIONS,"/**").permitAll().anyRequest().authenticated()).addFilterBefore(loginRateLimit,JwtAuthenticationFilter.class).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build(); }
}
